--sql_divide_splitter--

CREATE TEMPORARY VIEW dwm_search_user_keyword_raw_${grass_region_without_quote} AS
SELECT
    user_id
    ,device_id
    ,keyword
    ,page_type
    ,page_section
    ,target_type
    ,IF(is_ads IS NOT NULL, is_ads, 'false') AS is_ads
    ,IF(search_entrance IS NOT NULL AND TRIM(LOWER(search_entrance)) != '', TRIM(LOWER(search_entrance)), 'NA') AS search_entrance
    ,imp_cnt
    ,click_cnt
    ,view_cnt
    ,ppv_cnt
    ,cart_cnt
    ,order_cnt
    ,gmv
    ,pc2_gmv
FROM
    srdi_mart.dws_sr_data_warehouse_search_srp_user_benchmark_1d
WHERE
    local_date = ${local_date}
    AND grass_region = ${grass_region}
    AND page_type IN ('global_search', 'search_in_pdp', 'search_prefill')
    AND user_id > 0;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_search_feature_${grass_region_without_quote} AS
SELECT
    user_id
    ,device_id
    ,keyword
    ,CASE
        WHEN page_section IS NULL AND target_type = 'item' THEN 'item'
        WHEN page_section IS NULL AND target_type = 'video' THEN 'video'
        WHEN page_section IS NULL AND target_type = 'livestream' THEN 'livestream'
        ELSE 'Other'
    END AS card_type
    ,CAST(is_ads AS STRING) AS is_ads
    ,search_entrance
    
    ,SUM(imp_cnt) AS imp_cnt
    ,SUM(click_cnt) AS click_cnt
    ,SUM(view_cnt) AS view_cnt
    ,SUM(ppv_cnt) AS ppv_cnt
    ,SUM(cart_cnt) AS cart_cnt
    ,SUM(order_cnt) AS order_cnt
    ,SUM(gmv) AS gmv
    ,SUM(pc2_gmv) AS pc2_gmv
    ,SUM(IF(page_type IN ('global_search', 'search_in_pdp', 'search_prefill') AND view_cnt > 0, view_cnt, NULL)) AS search_cnt
    ,SUM(IF(click_cnt > 0 AND target_type IN ('item','video','livestream')
        AND page_type IN ('global_search', 'search_in_pdp', 'search_prefill')
        AND page_section IS NULL, 1, NULL)
    ) AS direct_search_success_cnt
    ,SUM(IF(click_cnt > 0 AND page_type IN ('global_search', 'search_in_pdp', 'search_prefill') 
        AND ((target_type IN ('item','video','livestream', 'curated_search', 'live_stream_floating_preview') AND page_section IS NULL)
            OR ((target_type like 'shop%' or target_type like 'creator%') AND page_section IS NULL)
            OR (page_section = 'creator')
        ), 1, NULL)
    ) AS broad_search_success_cnt
FROM
    dwm_search_user_keyword_raw_${grass_region_without_quote}
GROUP BY
    1,2,3,4,5,6;

--sql_divide_splitter--

CREATE TEMPORARY VIEW search_entrance_flatten_${grass_region_without_quote} AS
SELECT
    user_id
    ,device_id
    ,keyword
    ,card_type
    ,is_ads
    ,search_entrance
    ,imp_cnt
    ,click_cnt
    ,view_cnt
    ,ppv_cnt
    ,cart_cnt
    ,order_cnt
    ,gmv
    ,pc2_gmv
    ,search_cnt
    ,direct_search_success_cnt
    ,broad_search_success_cnt
FROM 
    dws_search_feature_${grass_region_without_quote}
UNION ALL
SELECT
    user_id
    ,device_id
    ,keyword
    ,card_type
    ,is_ads
    ,if(search_entrance IN ('live_search', 'video_search', 'content_mix_search'), 'all_content_search', 'not_content_search') AS search_entrance
    ,imp_cnt
    ,click_cnt
    ,view_cnt
    ,ppv_cnt
    ,cart_cnt
    ,order_cnt
    ,gmv
    ,pc2_gmv
    ,search_cnt
    ,direct_search_success_cnt
    ,broad_search_success_cnt
FROM 
    dws_search_feature_${grass_region_without_quote};

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_entrance_${grass_region_without_quote} AS
SELECT
    user_id
    ,IF(card_type IS NOT NULL, card_type, '__ALL__') AS card_type
    ,IF(is_ads IS NOT NULL, cast(is_ads AS STRING), '__ALL__') AS is_ads
    ,'__ALL__' AS search_entrance
    ,SUM(IF(card_type IN ('item', 'video', 'livestream'), imp_cnt, 0)) AS imp_cnt
    ,SUM(IF(card_type IN ('item', 'video', 'livestream'), click_cnt, 0)) AS click_cnt
    ,SUM(view_cnt) AS view_cnt
    ,SUM(IF(card_type IN ('item', 'video', 'livestream'), ppv_cnt, 0)) AS ppv_cnt
    ,SUM(IF(card_type IN ('item', 'video', 'livestream'), cart_cnt, 0)) AS cart_cnt
    ,SUM(IF(card_type IN ('item', 'video', 'livestream'), order_cnt, 0)) AS order_cnt
    ,SUM(IF(card_type IN ('item', 'video', 'livestream'), gmv, 0)) AS gmv
    ,SUM(IF(card_type IN ('item', 'video', 'livestream'), pc2_gmv, 0)) AS pc2_gmv
FROM
    dws_search_feature_${grass_region_without_quote}
WHERE
    card_type IN ('item', 'video', 'livestream')
    OR view_cnt > 0
GROUP BY GROUPING SETS
    ((user_id, card_type, is_ads), (user_id, card_type),(user_id, is_ads), (user_id))
UNION ALL
SELECT
    user_id
    ,IF(card_type IS NOT NULL, card_type, '__ALL__') AS card_type
    ,IF(is_ads IS NOT NULL, cast(is_ads AS STRING), '__ALL__') AS is_ads
    ,search_entrance
    ,SUM(IF(card_type IN ('item', 'video', 'livestream'), imp_cnt, 0)) AS imp_cnt
    ,SUM(IF(card_type IN ('item', 'video', 'livestream'), click_cnt, 0)) AS click_cnt
    ,SUM(view_cnt) AS view_cnt
    ,SUM(IF(card_type IN ('item', 'video', 'livestream'), ppv_cnt, 0)) AS ppv_cnt
    ,SUM(IF(card_type IN ('item', 'video', 'livestream'), cart_cnt, 0)) AS cart_cnt
    ,SUM(IF(card_type IN ('item', 'video', 'livestream'), order_cnt, 0)) AS order_cnt
    ,SUM(IF(card_type IN ('item', 'video', 'livestream'), gmv, 0)) AS gmv
    ,SUM(IF(card_type IN ('item', 'video', 'livestream'), pc2_gmv, 0)) AS pc2_gmv
FROM
    search_entrance_flatten_${grass_region_without_quote}
WHERE
    card_type in ('item', 'video', 'livestream')
    OR view_cnt > 0
GROUP BY GROUPING SETS
    ((user_id, search_entrance, card_type, is_ads), (user_id, search_entrance, card_type),(user_id, search_entrance, is_ads), (user_id, search_entrance));

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_main_metrics_${grass_region_without_quote} AS
SELECT
    exp_group_id
    ,card_type
    ,is_ads
    ,search_entrance
    ,SUM(imp_cnt) AS imp_cnt
    ,SUM(IF(imp_cnt > 0, 1, NULL)) AS imp_uu
    ,SUM(click_cnt) AS click_cnt
    ,SUM(IF(click_cnt > 0, 1, NULL)) AS click_uu
    ,SUM(view_cnt) AS view_cnt
    ,SUM(IF(view_cnt > 0, 1, NULL)) AS view_uu
    ,SUM(ppv_cnt) AS ppv_cnt
    ,SUM(IF(ppv_cnt > 0, 1, NULL)) AS ppv_uu
    ,SUM(cart_cnt) AS cart_cnt
    ,SUM(IF(cart_cnt > 0, 1, NULL)) AS cart_uu
    ,SUM(order_cnt) AS order_cnt
    ,SUM(IF(order_cnt > 0, 1, NULL)) AS order_uu
    ,SUM(gmv) AS gmv
    ,SUM(pc2_gmv) AS pc2_gmv
FROM
    dws_entrance_${grass_region_without_quote} a
JOIN
    user_exp_mapping_${grass_region_without_quote} b
ON
    a.user_id = b.user_id
GROUP BY
    1,2,3,4;

--sql_divide_splitter--
-- search volume metric --
CREATE TEMPORARY VIEW dwm_search_volume_${grass_region_without_quote} AS
SELECT
    user_id
    ,'__ALL__' AS search_entrance
    ,COUNT(DISTINCT CASE WHEN search_cnt > 0 THEN (device_id, keyword) ELSE NULL END) AS search_volume
    ,COUNT(DISTINCT CASE WHEN direct_search_success_cnt > 0 THEN (device_id, keyword) ELSE NULL END) AS direct_search_success_volume
    ,COUNT(DISTINCT CASE WHEN broad_search_success_cnt > 0 THEN (device_id, keyword) ELSE NULL END) AS broad_search_success_volume
FROM
    dws_search_feature_${grass_region_without_quote}
GROUP BY
    1,2
UNION ALL
SELECT
    user_id
    ,search_entrance
    ,COUNT(DISTINCT CASE WHEN search_cnt > 0 THEN (device_id, keyword) ELSE NULL END) AS search_volume
    ,COUNT(DISTINCT CASE WHEN direct_search_success_cnt > 0 THEN (device_id, keyword) ELSE NULL END) AS direct_search_success_volume
    ,COUNT(DISTINCT CASE WHEN broad_search_success_cnt > 0 THEN (device_id, keyword) ELSE NULL END) AS broad_search_success_volume
FROM
    search_entrance_flatten_${grass_region_without_quote}
GROUP BY
    1,2;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_search_volume_${grass_region_without_quote} AS 
SELECT
    exp_group_id
    ,search_entrance
    ,SUM(search_volume) AS search_volume
    ,SUM(direct_search_success_volume) AS direct_search_success_volume
    ,SUM(broad_search_success_volume) AS broad_search_success_volume
FROM
    dwm_search_volume_${grass_region_without_quote} a 
INNER JOIN
    user_exp_mapping_${grass_region_without_quote} b
ON
    a.user_id = b.user_id
GROUP BY 
    1,2;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_search_uu_${grass_region_without_quote} AS
SELECT
    exp_group_id
    ,'__ALL__' AS search_entrance
    ,COUNT(DISTINCT a.user_id) AS search_uu
FROM
    dws_search_feature_${grass_region_without_quote} a
JOIN
    user_exp_mapping_${grass_region_without_quote} b
ON
    a.user_id = b.user_id
WHERE
    view_cnt > 0
GROUP BY
    1,2
UNION ALL
SELECT
    exp_group_id
    ,search_entrance
    ,COUNT(DISTINCT a.user_id) AS search_uu
FROM
    search_entrance_flatten_${grass_region_without_quote} a
JOIN
    user_exp_mapping_${grass_region_without_quote} b
ON
    a.user_id = b.user_id
WHERE
    view_cnt > 0
GROUP BY
    1,2;

--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_search_abtest_entrance_card_type_core_metrics_1d
PARTITION (
    grass_region = ${grass_region}
    ,local_date = ${local_date}
)
SELECT
    scene_id
    ,scene_name
    ,layer_id
    ,layer_name
    ,experiment_id
    ,experiment_name
    ,a.exp_group_id
    ,exp_group_name
    ,is_ads
    ,a.card_type
    ,a.search_entrance

    ,exp_group_uu
    ,imp_cnt
    ,imp_uu
    ,click_cnt
    ,click_uu
    ,ppv_cnt
    ,ppv_uu
    ,cart_cnt
    ,cart_uu
    ,order_cnt
    ,order_uu
    ,gmv
    ,pc2_gmv
    ,search_uu
    ,search_volume
    ,direct_search_success_volume
    ,broad_search_success_volume
FROM
    dws_main_metrics_${grass_region_without_quote} a
LEFT JOIN
    dim_exp_${grass_region_without_quote} b
ON
    a.exp_group_id = b.exp_group_id
LEFT JOIN
    dws_exp_uu_${grass_region_without_quote} c
ON
    a.exp_group_id = c.exp_group_id
LEFT JOIN
    dws_search_volume_${grass_region_without_quote} d
ON
    a.exp_group_id = d.exp_group_id
    AND a.search_entrance = d.search_entrance
    AND a.is_ads = '__ALL__'
    AND a.card_type = '__ALL__'
LEFT JOIN
    dws_search_uu_${grass_region_without_quote} e
ON
    a.exp_group_id = e.exp_group_id
    AND a.search_entrance = e.search_entrance
    AND a.is_ads = '__ALL__'
    AND a.card_type = '__ALL__';
